package com.itsluminous.hikviewer.res

import com.google.common.truth.Truth.assertThat
import org.junit.Test
import java.io.File

/**
 * The Android TV launcher banner must be exactly 320 x 180 px in `drawable-xhdpi` (the home
 * screen shows it at that size and Lint rejects any other). The file is generated by
 * `scripts/gen-banner.py`, which also proves the name's ink stays inside the padding; this test
 * guards the committed bytes by reading the lossless WebP header directly, since Robolectric's
 * bitmap decoding does not understand WebP.
 */
class BannerTest {
    private val banner = File("src/main/res/drawable-xhdpi/banner.webp")

    @Test
    fun `the TV banner is a 320 x 180 lossless WebP`() {
        val bytes = banner.readBytes()
        assertThat(String(bytes, 0, 4, Charsets.US_ASCII)).isEqualTo("RIFF")
        assertThat(String(bytes, 8, 4, Charsets.US_ASCII)).isEqualTo("WEBP")
        assertThat(String(bytes, 12, 4, Charsets.US_ASCII)).isEqualTo("VP8L")
        assertThat(bytes[20].toInt() and 0xFF).isEqualTo(0x2F) // VP8L signature
        val bits = (0 until 4).fold(0L) { acc, i -> acc or ((bytes[21 + i].toLong() and 0xFF) shl (8 * i)) }
        val width = (bits and 0x3FFF).toInt() + 1
        val height = ((bits shr 14) and 0x3FFF).toInt() + 1
        assertThat(width).isEqualTo(320)
        assertThat(height).isEqualTo(180)
    }

    @Test
    fun `the manifest points the TV launcher at it`() {
        val manifest = File("src/main/AndroidManifest.xml").readText()
        assertThat(manifest).contains("android:banner=\"@drawable/banner\"")
        assertThat(manifest).contains("android.intent.category.LEANBACK_LAUNCHER")
    }
}
